filename = '../atOut/healthcare_6_6_atomic-Out.txt';
T = 10;
ALPHA = 1.0;
BETA = 0.01;
N = 10;
SEED = 3;
OUTPUT = 0;
tic
[ WP, AT , Z , X ] = GibbsSamplerAT( WS , DS , AD , T , N , ALPHA , BETA , SEED , OUTPUT );
toc
save '../atOut/healthcare_6_6_atomic-Out' WP AT Z X ALPHA BETA SEED N;
WPM{1} = WP; WPM{2} = AT;
BETAM(1)=BETA; BETAM(2) = ALPHA;
WOM{1}=WO; WOM{2}=AN;
[ SM ] = WriteTopicsMult( WPM , BETAM , WOM , 3 , 1.1 , 1 , filename );
